mapper.select:
SELECT COUNT(*)
FROM bq_registration
WHERE deleted = 0
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT COUNT(*)
FROM bq_registration
WHERE deleted = 0
  AND status = '已接诊'
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT COUNT(*)
FROM bq_registration
WHERE deleted = 0
  AND status = '待接诊'
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT COALESCE(SUM(totalPrice), 0)
FROM bq_registration
WHERE deleted = 0
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT COUNT(*)
FROM bq_registration
WHERE deleted = 0
  AND doctor = #{doctor}
  AND status = '已接诊'
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT COUNT(*)
FROM bq_registration
WHERE deleted = 0
  AND doctor = #{doctor}
  AND status = '待接诊'
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT COALESCE(SUM(totalPrice), 0)
FROM bq_registration
WHERE deleted = 0
  AND doctor = #{doctor}
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}

SELECT doctor, department, COUNT(*) AS count
FROM bq_registration
WHERE deleted = 0
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}
GROUP BY doctor, department
ORDER BY count DESC
LIMIT #{limit}

SELECT doctor, department, SUM(totalPrice) AS fee
FROM bq_registration
WHERE deleted = 0
  AND orderTime >= #{dayStart}
  AND orderTime < #{dayEnd}
GROUP BY doctor, department
ORDER BY fee DESC
LIMIT #{limit}
